arguments.command:
cd /work && timeout 300 python3 - << 'PY'
import importlib.util, json, time
def load(n,p):
    s=importlib.util.spec_from_file_location(n,p); m=importlib.util.module_from_spec(s); s.loader.exec_module(m); return m
mn=load("m","/work/submission/main.py"); rf=load("r","/work/tmp/dev/ref.py")
n=96; dest=95
pairs=set()
for i in range(dest): pairs.add((i,i+1))
for a in [3+7*k for k in range(13)]:
    pairs.discard((a,a+1))
    pairs |= {(a-1,a),(a,a+2),(a-1,a+1),(a+1,a+2)}
pairs=sorted(pairs)
edges=[{"u":u,"v":v,"ping_us":2,"ack_us":1,"label":"ab" if i%3 else "c%d"%i} for i,(u,v) in enumerate(pairs)]
doc={"version":1,"n":n,"capacity":[3]*n,"edges":edges,
     "rounds":[{"launch_us":0,"timeout_us":400,"host_delay_us":1,"drop_host_ack":False,
                "drop_ping":[5,17],"drop_ack":[3]},
               {"launch_us":0,"timeout_us":10**6,"host_delay_us":2,"drop_host_ack":True,
                "drop_ping":[],"drop_ack":[]}]}
blob=json.dumps(doc)
t=time.time(); a=mn.run(json.loads(blob)); ta=time.time()-t
t=time.time(); b=rf.run(json.loads(blob)); tb=time.time()-t
print("paths",a["summary"]["topology_paths"],"classes",a["summary"]["observable_classes"],
      "observed",a["summary"]["observed_classes"],"main %.2fs ref %.2fs"%(ta,tb),
      "MATCH" if a==b else "DIFF")
if a!=b:
    for k in ("metrics","summary"):
        if a[k]!=b[k]: print(k,"main",json.dumps(a[k])[:500],"\n     ref ",json.dumps(b[k])[:500])
    if a["rounds"]!=b["rounds"]: print("rounds main",json.dumps(a["rounds"])[:400],"\n      ref",json.dumps(b["rounds"])[:400])
    if a["classes"]!=b["classes"]:
        for x,y in zip(a["classes"],b["classes"]):
            if x!=y: print("cls main",json.dumps(x)[:300],"\n    ref ",json.dumps(y)[:300]); break
print("metrics", json.dumps({k:v for k,v in a["metrics"].items() if k!="cache_peak"}))
PY
